CREATE OR REPLACE FUNCTION eflow_m7.guard_root_start()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare lead uuid; root jsonb;
begin
 if new.status='in_progress' and old.status in ('todo','pending_assignment','changes_requested') then
  if tg_table_name='tasks' then lead:=old.assigned_to; else lead:=old.lead_id; end if;
  root:=eflow_r7.root(new.id);
  if lead is null or lead is distinct from auth.uid() or not coalesce(eflow_r3.eligible(lead),false)
     or root is not null and not coalesce(eflow_r7.read_root(new.id),false) then
   raise exception 'Only the appointed Task Lead can start this task' using errcode='42501';
  end if;
  if tg_table_name='tasks' and old.status in ('todo','pending_assignment')
     and coalesce((to_jsonb(old)->>'start_date')::date > eflow_m7.work_day(new.id), true) then
   if to_jsonb(old)->>'start_date' is null then
     raise exception 'Set a planned start date before starting this task.' using errcode='22023';
   end if;
   raise exception 'You can start this task on or after %.', to_jsonb(old)->>'start_date' using errcode='22023';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_m7.schedule_node()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare root jsonb := eflow_r7.root(new.task_id); today date := eflow_m7.work_day(new.task_id);
 ancestor uuid := new.parent_subtask_id; n eflow_r7.nodes;
 parent_start date; parent_due date; eligible boolean := true;
begin
 if tg_op = 'UPDATE' then
  if new.started_at is distinct from old.started_at and not exists (
    select 1 from eflow_m7.activation a where a.tx=txid_current() and a.root=new.task_id
  ) then raise exception 'Subtask start time is managed by the lifecycle' using errcode='42501'; end if;
  if new.start_date is not distinct from old.start_date and new.due_date is not distinct from old.due_date
    and new.parent_subtask_id is not distinct from old.parent_subtask_id then return new; end if;
  if new.start_date is null and old.start_date is not null then
   raise exception 'Keep a planned start date for scheduled work' using errcode='22023';
  end if;
  if old.started_at is not null and new.start_date is distinct from old.start_date then
   raise exception 'A started subtask retains its planned start date' using errcode='22023';
  end if;
 else
  new.started_at := null;
  null; -- The default is assigned after the ancestor range is read.
 end if;
 if tg_op='UPDATE' and new.start_date is null then return new; end if;
 if root->>'kind' = 'office' then
  select t.start_date::date into parent_start from public.tasks t where t.id=new.task_id;
 end if;
 while ancestor is not null loop
  select * into n from eflow_r7.nodes where id=ancestor and task_id=new.task_id;
  if not found then raise exception 'Parent is unavailable in this work tree' using errcode='23514'; end if;
  if tg_table_name='subtasks' then
   select s.start_date into parent_due from public.subtasks s where s.id=n.id;
  else
   select s.start_date into parent_due from public.personal_subtasks s where s.id=n.id;
  end if;
  parent_start := greatest(parent_start,parent_due);
  eligible := eligible and n.status not in ('completed','for_review');
  ancestor := n.parent_subtask_id;
 end loop;
 if tg_op='INSERT' then new.start_date := coalesce(new.start_date,parent_start,today); end if;
 if new.start_date < parent_start or new.start_date > new.due_date then
  raise exception 'Choose a start date within the parent schedule, or reschedule the parent first' using errcode='22023';
 end if;
 if tg_op='INSERT' and eligible and new.status='todo' and new.start_date<=today
    and root->>'status'='in_progress' and (root->>'open')::boolean then
  null; -- Subtask activation requires an explicit Lead command.
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_m7.validate_subtask_date_range()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare earliest date; latest date; ancestor uuid := new.parent_subtask_id; parent record;
 visited uuid[] := array[new.id];
begin
 if tg_op='UPDATE' and row(new.start_date,new.due_date,new.parent_subtask_id)
  is not distinct from row(old.start_date,old.due_date,old.parent_subtask_id) then return new; end if;
 if tg_table_name='subtasks' then
  select t.start_date,coalesce(nullif(left(t.due_date::text,10),''),nullif(left(t.deadline::text,10),''))::date
  into earliest,latest from public.tasks t where t.id=new.task_id;
 end if;
 while ancestor is not null loop
  if ancestor=any(visited) then raise exception 'Parent is unavailable in this work tree' using errcode='23514'; end if;
  visited := array_append(visited,ancestor);
  if tg_table_name='subtasks' then
   select s.start_date,s.due_date,s.parent_subtask_id into parent from public.subtasks s where s.id=ancestor and s.task_id=new.task_id;
  else
   select s.start_date,s.due_date,s.parent_subtask_id into parent from public.personal_subtasks s where s.id=ancestor and s.task_id=new.task_id;
  end if;
  if not found then raise exception 'Parent is unavailable in this work tree' using errcode='23514'; end if;
  earliest := greatest(earliest,parent.start_date);
  latest := least(latest,parent.due_date);
  ancestor := parent.parent_subtask_id;
 end loop;
 if new.start_date < earliest or new.start_date > latest then
  raise exception 'Choose a start date within the parent schedule, or reschedule the parent first' using errcode='22023';
 end if;
 if new.due_date < earliest or new.due_date > latest or new.due_date < new.start_date then
  raise exception 'Choose a due date between the subtask start and the parent deadline' using errcode='22023';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_r7.check_subtask_dependency_graph()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare root_id uuid; changed_id uuid;
begin
 root_id:=case when tg_op='DELETE' then old.task_id else new.task_id end;
 changed_id:=case when tg_op='DELETE' then old.id else new.id end;
 if tg_op='UPDATE' and row(new.dependency_ids,new.task_id,new.parent_subtask_id,new.sibling_order,new.is_standalone,new.status,new.due_date)
  is not distinct from row(old.dependency_ids,old.task_id,old.parent_subtask_id,old.sibling_order,old.is_standalone,old.status,old.due_date) then return null; end if;
 if tg_op<>'INSERT' and exists (
   select 1 from public.subtasks d left join public.subtasks s on s.id=changed_id
   where d.dependency_ids @> array[changed_id] and d.status<>'cancelled'
    and (s.id is null or s.task_id<>d.task_id or s.parent_subtask_id is distinct from d.parent_subtask_id
      or s.status='cancelled' or (d.started_at is not null or d.status in ('in_progress','for_review','completed')) and s.status<>'completed'
      or s.status<>'completed' and s.due_date>d.start_date)
 ) then
  raise exception 'Resolve dependent subtasks before changing or removing this prerequisite.' using errcode='23514';
 end if;
 if (tg_op='INSERT' or tg_op='DELETE' or row(new.task_id,new.parent_subtask_id,new.dependency_ids)
    is distinct from row(old.task_id,old.parent_subtask_id,old.dependency_ids)) and exists (
   select 1 from public.subtasks d cross join lateral unnest(d.dependency_ids) ref(id)
   left join public.subtasks p on p.id=ref.id
   where d.id=changed_id and d.status<>'cancelled'
    and (p.id is null or p.task_id<>d.task_id or p.parent_subtask_id is distinct from d.parent_subtask_id or p.status='cancelled')
 ) then
  raise exception 'Resolve this subtask’s prerequisites before moving it.' using errcode='23514';
 end if;
 if not exists(select 1 from public.subtasks s where s.task_id=root_id and cardinality(s.dependency_ids)>0 and s.status<>'cancelled') then return null;end if;
 if exists(
  with recursive edges as (
   select s.id,ref.id as prerequisite from public.subtasks s cross join lateral unnest(s.dependency_ids) ref(id)
   where s.task_id=root_id and s.status<>'cancelled'
   union all
   select s.id,p.id from public.subtasks s join public.subtasks p
    on p.task_id=s.task_id and p.parent_subtask_id is not distinct from s.parent_subtask_id and p.sibling_order<s.sibling_order
   where s.task_id=root_id and s.dependency_ids is null and s.status not in ('completed','cancelled')
    and not s.is_standalone and not p.is_standalone and p.status<>'completed'
  ), chain(origin,step) as (
   select s.id,ref.id from public.subtasks s cross join lateral unnest(s.dependency_ids) ref(id)
    where s.task_id=root_id and s.status<>'cancelled'
   union
   select c.origin,e.prerequisite from chain c join edges e on e.id=c.step where c.step<>c.origin
  ) select 1 from chain where origin=step
 ) then raise exception 'Dependencies cannot form a circular chain.' using errcode='23514';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION eflow_schedule.guard_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p record; due date;
BEGIN
  IF NEW.linked_project_id IS NULL OR NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(NEW.linked_project_id, NEW.start_date, NEW.deadline, NEW.due_date, NEW.deleted_at)
      IS NOT DISTINCT FROM ROW(OLD.linked_project_id, OLD.start_date, OLD.deadline, OLD.due_date, OLD.deleted_at) THEN
      RETURN NEW;
    END IF;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('r9:' || NEW.linked_project_id::text, 0));
  SELECT start_date, target_date INTO p FROM public.projects WHERE id = NEW.linked_project_id;
  IF NOT FOUND THEN RETURN NEW; END IF; -- Existing FK/link guards handle this.
  due := coalesce(eflow_schedule.calendar_day(nullif(NEW.deadline, '')),
    eflow_schedule.calendar_day(NEW.due_date));
  IF NEW.start_date IS NOT NULL AND due < NEW.start_date THEN
    RAISE EXCEPTION 'Task due date cannot be before its start date.' USING ERRCODE = '22023';
  END IF;
  IF p.start_date IS NOT NULL AND least(NEW.start_date, due) < p.start_date THEN
    RAISE EXCEPTION 'Task dates cannot be before the project start date (%). Extend the project timeline first.', p.start_date USING ERRCODE = '22023';
  END IF;
  IF p.target_date IS NOT NULL AND greatest(NEW.start_date, due) > p.target_date THEN
    RAISE EXCEPTION 'Task dates cannot be after the project target date (%). Extend the project timeline first.', p.target_date USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION eflow_schedule.guard_web_subtask_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_id uuid;
  v_parent_task_id uuid;
  first_day date;
  last_day date;
  conflicting_title text;
BEGIN
  IF tg_table_name = 'projects' THEN
    IF ROW(new.start_date, new.target_date)
       IS NOT DISTINCT FROM ROW(old.start_date, old.target_date)
    THEN
      RETURN new;
    END IF;

    v_project_id := new.id;
    first_day := new.start_date;
    last_day := new.target_date;
  ELSE
    IF new.deleted_at IS NOT NULL
       OR ROW(new.start_date, new.deadline, new.due_date, new.linked_project_id)
          IS NOT DISTINCT FROM
          ROW(old.start_date, old.deadline, old.due_date, old.linked_project_id)
    THEN
      RETURN new;
    END IF;

    v_parent_task_id := new.id;
    v_project_id := new.linked_project_id;
    first_day := new.start_date;
    last_day := LEAST(
      eflow_schedule.calendar_day(new.deadline),
      eflow_schedule.calendar_day(new.due_date)
    );
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      CASE
        WHEN v_project_id IS NULL
          THEN 'subtask-schedule:' || v_parent_task_id
        ELSE 'r9:' || v_project_id
      END,
      0
    )
  );

  IF v_parent_task_id IS NOT NULL THEN
    SELECT
      GREATEST(first_day, p.start_date),
      LEAST(last_day, p.target_date)
    INTO first_day, last_day
    FROM (SELECT 1) seed
    LEFT JOIN public.projects p ON p.id = v_project_id;
  END IF;

  SELECT s.title
  INTO conflicting_title
  FROM public.subtasks s
  JOIN public.tasks t ON t.id = s.task_id
  WHERE t.deleted_at IS NULL
    AND (
      CASE
        WHEN v_parent_task_id IS NULL
          THEN t.linked_project_id = v_project_id
        ELSE t.id = v_parent_task_id
      END
    )
    AND (
      LEAST(s.start_date, s.due_date) < first_day
      OR GREATEST(s.start_date, s.due_date) > last_day
    )
  ORDER BY s.id
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Reschedule subtask "%" before changing this timeline.',
      conflicting_title
      USING ERRCODE = '22023';
  END IF;

  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION eflow_schedule.guard_web_subtask_plan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare first_day date; last_day date; project_id uuid;
begin
  -- The versioned planning command sets this transaction's verified marker.
  -- Existing legacy INSERTs can keep the default. Assigned workers' UPDATE
  -- policy for execution does not grant permission to change priority.
  if tg_op='INSERT' then
    if new.priority<>'medium' and not coalesce(eflow_r7.internal(new.task_id),false) then
      raise exception 'Use the authorized subtask command to set priority.' using errcode='42501';
    end if;
  elsif new.priority is distinct from old.priority and not coalesce(eflow_r7.internal(new.task_id),false) then
    raise exception 'Use the authorized subtask command to edit priority.' using errcode='42501';
  end if;
  if new.parent_subtask_id is not null then
    if tg_op='INSERT' then
      raise exception 'Add subtasks directly to their task.' using errcode='22023';
    elsif new.parent_subtask_id is distinct from old.parent_subtask_id then
      raise exception 'Move subtasks directly to their task.' using errcode='22023';
    end if;
  end if;
  if tg_op='UPDATE' then
    if row(new.start_date,new.due_date) is not distinct from row(old.start_date,old.due_date) then return new; end if;
    if not coalesce(eflow_r7.internal(new.task_id),false)
      and not coalesce(public.can_manage_subtasks(new.task_id,auth.uid()),false) then
      raise exception 'Only the current planning authority can change the subtask schedule.' using errcode='42501';
    end if;
    if nullif(btrim(new.due_date_change_reason),'') is null then
      raise exception 'Enter a reason for the schedule change.' using errcode='22023';
    end if;
  end if;
  select t.linked_project_id into project_id from public.tasks t where t.id=new.task_id;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    case when project_id is null then 'subtask-schedule:'||new.task_id else 'r9:'||project_id end,0));
  select greatest(t.start_date,p.start_date),
    least(eflow_schedule.calendar_day(t.deadline),eflow_schedule.calendar_day(t.due_date),p.target_date)
  into first_day,last_day from public.tasks t left join public.projects p on p.id=t.linked_project_id
  where t.id=new.task_id;
  if new.start_date is not null and ((project_id is not null and new.due_date is null) or new.start_date>new.due_date)
    or least(new.start_date,new.due_date)<first_day or greatest(new.start_date,new.due_date)>last_day then
    raise exception 'Keep the subtask start and due dates within the task and project schedule.' using errcode='22023';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_subtask_execution_dependencies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

declare

  workflow_authorized boolean :=

    coalesce(current_setting('eflow.subtask_workflow_authorized', true), 'off') = 'on';

  blocking_title text;

  blocking_step integer;

begin

  -- Direct edits are handled by guard_subtask_contributor_update. Execution

  -- dependencies apply to the evidence/progress RPC workflow only.

  if not workflow_authorized then

    if new.is_standalone is distinct from old.is_standalone

       and (old.status <> 'todo' or old.percent_complete > 0) then

      raise exception 'Execution mode cannot change after subtask work has started'

        using errcode = '22023',

          hint = 'Reset or finish the existing work before changing between sequential and standalone.';

    end if;

    return new;

  end if;



  -- A reviewer must still be able to approve or request changes for evidence

  -- that was valid when submitted.

  if old.status = 'for_review' or new.is_standalone or new.dependency_ids is not null then

    return new;

  end if;



  select prerequisite.title, (

    select count(*)::integer

    from public.subtasks numbered

    where numbered.task_id = prerequisite.task_id

      and numbered.is_standalone = false

      and numbered.parent_subtask_id is not distinct from prerequisite.parent_subtask_id and numbered.sibling_order <= prerequisite.sibling_order

  )

    into blocking_title, blocking_step

  from public.subtasks prerequisite

  where prerequisite.task_id = new.task_id

    and prerequisite.id <> new.id

    and prerequisite.parent_subtask_id is not distinct from new.parent_subtask_id and prerequisite.sibling_order < new.sibling_order

    and prerequisite.is_standalone = false

    and prerequisite.is_completed = false

  order by prerequisite.sibling_order, prerequisite.created_at, prerequisite.id

  limit 1;



  if blocking_title is not null then

    raise exception 'Complete Step %: "%" before starting this subtask',

      blocking_step, blocking_title

      using errcode = '22023',

        detail = 'Complete ordered subitems in sequence.',

        hint = 'Ask the Team Lead to mark this subtask Standalone only when it is genuinely independent.';

  end if;



  return new;

end;

$function$

CREATE OR REPLACE FUNCTION public.guard_task_dependency_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare required_count integer;completed_count integer;
begin
 if new.status::text not in ('for_review','completed') or cardinality(coalesce(new.dependency_ids,'{}'::uuid[]))=0 then return new;end if;
 required_count:=cardinality(new.dependency_ids);
 perform 1 from public.tasks t where t.id=any(new.dependency_ids) order by t.id for share;
 select count(*) into completed_count from public.tasks t where t.id=any(new.dependency_ids)
  and t.linked_project_id is not distinct from new.linked_project_id and t.status::text='completed' and t.deleted_at is null;
 if completed_count<>required_count then raise exception 'Wait for prerequisite task approval before final submission.' using errcode='22023';end if;
 return new;
end $function$
